input.command:
cd /app; cat > tests/price_test.sh <<'E'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
# Spec: 10% off, rounded down. 999*0.9=899.1 -> 899; 1*0.9=0.9 -> 0
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999: got $(bash bin/price 999), want 899"; fail=1; }
[ "$(bash bin/price 1)" = 0 ] || { echo "price 1: got $(bash bin/price 1), want 0"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999: got $(bash bin/quote 999)"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999: got $(bash lib/invoice.sh 999)"; fail=1; }
[ "$(bash -c 'source lib/receipt/line.sh; member_line 999')" = "receipt 899" ] || { echo "receipt 999: got $(bash -c 'source lib/receipt/line.sh; member_line 999')"; fail=1; }
exit $fail
E
bash tests/price_test.sh; echo rc=$?
